#!/usr/bin/env python3
"""Create an offline ACT/sprite composition inspector from parsed metadata."""
import base64, json, mimetypes
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
BUILD=ROOT/'build'
acts=json.loads((BUILD/'analysis'/'act-index.json').read_text(encoding='utf-8'))
images={}
for p in sorted((BUILD/'assets'/'sprite').glob('*.png')):
    raw=p.read_bytes(); mime=mimetypes.guess_type(p.name)[0] or 'image/png'
    images[p.name]=f'data:{mime};base64,'+base64.b64encode(raw).decode('ascii')
# Legacy ACTs omit atlas filenames; the original Java loader falls back to ACT basename + .png.
for a in acts:
    if not a['imageFiles']:
        fallback=a['file'][:-4]+'.png'
        a['imageFiles']=[fallback] if fallback in images else []

html=r'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Tây Du Chiến Ký — Sprite/ACT Inspector</title><style>
:root{color-scheme:dark;--bg:#0d1118;--panel:#161e29;--line:#2b394a;--text:#e8edf4;--muted:#9aabc0;--gold:#e5b95c;--cyan:#65c9d7}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 Segoe UI,Arial,sans-serif}header{padding:18px 22px;background:#111925;border-bottom:1px solid var(--line)}h1{font-size:20px;margin:0 0 4px}header p{margin:0;color:var(--muted)}main{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:14px;padding:14px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:10px;overflow:hidden}.toolbar{padding:12px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;border-bottom:1px solid var(--line)}label{color:var(--muted)}select,input,button{background:#0d1520;color:var(--text);border:1px solid #3a4b60;border-radius:6px;padding:7px 9px}button{cursor:pointer}button:hover{border-color:var(--gold)}input[type=checkbox]{accent-color:var(--gold)}#stage{height:430px;display:grid;place-items:center;background:repeating-conic-gradient(#101720 0% 25%,#131c27 0% 50%) 50%/24px 24px;overflow:auto}canvas{image-rendering:pixelated;image-rendering:crisp-edges;background:#101720;border:1px solid #354458;box-shadow:0 2px 18px #0009}.timeline{display:flex;gap:9px;align-items:center;padding:12px;border-top:1px solid var(--line)}input[type=range]{flex:1;padding:0}.side{padding:14px}.side h2{font-size:15px;margin:0 0 8px;color:var(--gold)}.statgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}.stat{background:#0e1621;border:1px solid var(--line);border-radius:7px;padding:8px}.stat b{display:block;font-size:17px}.stat small{color:var(--muted)}#frames{max-height:300px;overflow:auto}.frameitem{padding:7px 0;border-bottom:1px solid #263342;color:var(--muted)}.note{margin:0 14px 14px;padding:10px 12px;color:var(--muted);background:#151e29;border:1px solid var(--line);border-radius:8px}@media(max-width:950px){main{grid-template-columns:1fr}.side{order:2}}
</style></head><body><header><h1>Tây Du Chiến Ký — Sprite / ACT Inspector</h1><p>Xem sprite ghép từ các vùng cắt, offset và frame metadata trong file ACT gốc. Hoạt động hoàn toàn offline.</p></header>
<main><section class="panel"><div class="toolbar"><label>ACT</label><select id="act"></select><label>Sequence</label><select id="seq"></select><label>Zoom</label><select id="zoom"><option value="1">100%</option><option value="2" selected>200%</option><option value="3">300%</option><option value="4">400%</option></select><label><input type="checkbox" id="bounds"> Bounds</label><label><input type="checkbox" id="parts" checked> Parts</label></div>
<div id="stage"><canvas id="view" width="480" height="360"></canvas></div><div class="timeline"><button id="prev">◀</button><button id="play">Phát</button><button id="next">▶</button><input id="frame" type="range" min="0" max="0" value="0"><span id="counter">0 / 0</span><label>Tốc độ <select id="speed"><option value="240">Chậm</option><option value="160">Vừa</option><option value="100" selected>Nhanh</option><option value="60">Rất nhanh</option></select></label></div></section>
<aside class="panel side"><h2>Thông tin ACT</h2><div class="statgrid" id="stats"></div><h2>Thành phần frame</h2><div id="frames"></div></aside></main>
<div class="note">Giới hạn hiện tại: inspector ghép đúng ảnh con, tọa độ cắt và offset lưu trong từng frame; chưa mô phỏng đầy đủ biến đổi hướng/đổi trục và logic căn chỉnh động của class Java `lx.game.m`. Các ACT legacy chưa được phân tích hết vẫn có thể chỉ hiện một phần. Dữ liệu nguồn không bị sửa.</div>
<script>
const ACTS=__ACTS__,IMAGES=__IMAGES__;const $=id=>document.getElementById(id);const canvas=$('view'),ctx=canvas.getContext('2d');let act=null,sequence=[],frameIndex=0,playing=false,timer=null;const imageCache={};
function imageFor(n){if(!imageCache[n]){imageCache[n]=new Image();imageCache[n].src=IMAGES[n]||'';imageCache[n].onload=()=>draw()}return imageCache[n]}
function spriteTransform(c,x,y,w,h,t){c.translate(x+w/2,y+h/2);switch(t){case 1:c.scale(1,-1);break;case 2:c.scale(-1,1);break;case 3:c.rotate(Math.PI);break;case 4:c.rotate(Math.PI/2);c.scale(1,-1);break;case 5:c.rotate(Math.PI/2);break;case 6:c.rotate(-Math.PI/2);break;case 7:c.rotate(-Math.PI/2);c.scale(1,-1);break;}}
function currentGroupId(){return sequence.length?sequence[frameIndex%sequence.length]:-1}
function draw(){if(!act)return;const gid=currentGroupId(),g=gid>=0?act.animations[gid]:null,z=Number($('zoom').value);canvas.width=240*z;canvas.height=180*z;canvas.style.width=canvas.width+'px';canvas.style.height=canvas.height+'px';ctx.setTransform(z,0,0,z,0,0);ctx.clearRect(0,0,240,180);ctx.fillStyle='#101720';ctx.fillRect(0,0,240,180);ctx.translate(120,145);
 if(!g){ctx.fillStyle='#aab6c5';ctx.font='12px sans-serif';ctx.fillText('Sequence không có frame để hiển thị',-105,0);return}
 const b=g.boundsA||[0,0,0,0];if($('bounds').checked){ctx.save();ctx.strokeStyle='rgba(229,185,92,.85)';ctx.setLineDash([3,2]);ctx.strokeRect(b[0],b[1],b[2],b[3]);ctx.restore()}
 if($('parts').checked){for(const f of g.frames||[]){const ri=f[0],r=act.rectangles[ri];if(!r)continue;const [sx,sy,w,h]=r;const imgName=act.imageFiles[r.length>4?r[4]:0]||act.imageFiles[0];if(!imgName||!IMAGES[imgName])continue;const im=imageFor(imgName);if(!im.complete||!im.naturalWidth)continue;ctx.save();spriteTransform(ctx,f[1],f[2],w,h,f[3]||0);ctx.drawImage(im,sx,sy,w,h,-w/2,-h/2,w,h);ctx.restore()}}
 }
function stop(){playing=false;if(timer)clearInterval(timer);timer=null;$('play').textContent='Phát'}function play(){if(!sequence.length)return;stop();playing=true;$('play').textContent='Tạm dừng';timer=setInterval(()=>{frameIndex=(frameIndex+1)%sequence.length;sync();draw()},Number($('speed').value))}
function sync(){if(!sequence.length){$('frame').max=0;$('frame').value=0;$('counter').textContent='0 / 0';return}$('frame').max=sequence.length-1;$('frame').value=frameIndex;$('counter').textContent=`${frameIndex+1} / ${sequence.length} · group ${sequence[frameIndex]}`}
function loadAct(name){stop();act=ACTS.find(a=>a.file===name);if(!act)return;const sel=$('seq');sel.innerHTML='';act.sequences.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`Sequence ${i} (${s.length} bước)`;sel.appendChild(o)});let preferred=act.file==='sunwk.act'?1:act.sequences.findIndex(s=>s.length>0);if(preferred<0)preferred=0;sel.value=String(preferred);loadSequence(preferred);for(const n of act.imageFiles)imageFor(n);$('stats').innerHTML=`<div class="stat"><b>${act.format}</b><small>Định dạng</small></div><div class="stat"><b>${act.rectangleCount}</b><small>Rectangles</small></div><div class="stat"><b>${act.animationCount}</b><small>Animation groups</small></div><div class="stat"><b>${act.sequenceCount}</b><small>Sequences</small></div><div class="stat"><b>${act.imageFiles.length}</b><small>Atlas images</small></div><div class="stat"><b>${act.unparsedTailBytes}</b><small>Byte dư chưa giải nghĩa</small></div>`;}
function loadSequence(i){stop();sequence=(act?.sequences?.[i]||[]).filter(x=>x>=0&&x<act.animations.length);frameIndex=0;sync();draw();$('frames').innerHTML='';sequence.forEach((gid,i)=>{const g=act.animations[gid],el=document.createElement('div');el.className='frameitem';el.textContent=`Bước ${i+1}: group ${gid} · ${g.frameCount} sprite parts`; $('frames').appendChild(el)})}
ACTS.forEach(a=>{const o=document.createElement('option');o.value=a.file;o.textContent=`${a.file} · ${a.format} · ${a.animationCount} groups`;$('act').appendChild(o)});
$('act').value='sunwk.act';loadAct('sunwk.act');$('act').addEventListener('change',e=>loadAct(e.target.value));$('seq').addEventListener('change',e=>loadSequence(Number(e.target.value)));$('zoom').addEventListener('change',draw);$('bounds').addEventListener('change',draw);$('parts').addEventListener('change',draw);$('frame').addEventListener('input',e=>{frameIndex=Number(e.target.value);sync();draw()});$('prev').addEventListener('click',()=>{if(!sequence.length)return;frameIndex=(frameIndex+sequence.length-1)%sequence.length;sync();draw()});$('next').addEventListener('click',()=>{if(!sequence.length)return;frameIndex=(frameIndex+1)%sequence.length;sync();draw()});$('play').addEventListener('click',()=>playing?stop():play());$('speed').addEventListener('change',()=>{if(playing)play()});
</script></body></html>'''
html=html.replace('__ACTS__',json.dumps(acts,ensure_ascii=False,separators=(',',':')))
html=html.replace('__IMAGES__',json.dumps(images,ensure_ascii=False,separators=(',',':')))
out=ROOT/'viewer'/'sprites.html';out.write_text(html,encoding='utf-8')
print(f'Wrote {out} ({out.stat().st_size:,} bytes), embedded {len(acts)} ACT and {len(images)} images')
